<?php require_once __DIR__ . '/includes/functions.php'; $pageTitle='Attractions';$q=trim($_GET['q']??''); try {
    $s=db()->prepare("SELECT a.*,d.name destination_name FROM attractions a JOIN destinations d ON d.id=a.destination_id WHERE a.status='active' AND (a.name LIKE ? OR a.short_description LIKE ?) ORDER BY a.name");
    $s->execute(["%$q%","%$q%"]);
    $items=$s->fetchAll();
} catch (Throwable $error) {
    $items=$q ? [] : [['name'=>'Heritage Museum','slug'=>'heritage-museum','destination_name'=>'Heritage District','short_description'=>'A hands-on journey through local history.','main_image'=>''],['name'=>'Forest Lookout','slug'=>'forest-lookout','destination_name'=>'Nature Escape','short_description'=>'A panoramic nature viewpoint.','main_image'=>''],['name'=>'Crafts Market','slug'=>'crafts-market','destination_name'=>'Cultural Village','short_description'=>'Meet makers and discover handmade treasures.','main_image'=>'']];
}require __DIR__.'/includes/header.php';?><section class="page-header"><div class="container"><div class="eyebrow">PLACES WORTH REMEMBERING</div><h1>Attractions</h1><p class="lead mb-0">Curated experiences to make every journey more meaningful.</p></div></section><section class="container filter-bar"><div class="card p-3"><form class="row g-2 align-items-center"><div class="col-md"><input class="form-control form-control-lg" name="q" value="<?=e($q)?>" placeholder="Search attractions"></div><div class="col-auto"><button class="btn btn-success btn-lg px-4"><i class="fa-solid fa-magnifying-glass"></i> Search</button></div></form></div></section><section class="container py-5"><div class="row g-4"><?php foreach ($items as $a):?><div class="col-md-6 col-lg-4"><div class="card h-100 attraction-card overflow-hidden"><img class="card-img-top" src="<?=$a['main_image'] ? asset($a['main_image']) : asset('images/hero.svg')?>" alt="<?=e($a['name'])?>"><div class="card-body d-flex flex-column"><small class="text-success fw-bold"><?=e($a['destination_name'])?></small><h5 class="mt-2"><?=e($a['name'])?></h5><p><?=e($a['short_description'])?></p><a href="<?=url('attraction.php?slug='.urlencode($a['slug']))?>" class="btn btn-success mt-auto align-self-start">View details <i class="fa-solid fa-arrow-right ms-1"></i></a></div></div></div><?php endforeach;?><?php if (!$items):?><div class="col-12"><div class="empty-state"><i class="fa-solid fa-landmark fa-2x mb-3"></i><h3>No attractions found</h3><p>Try a different search term or check back soon.</p></div></div><?php endif;?></div></section><?php require __DIR__.'/includes/footer.php';?>
